mapper.select:
SELECT a.*, o.order_no AS orderNo, o.pay_price AS refundPrice, o.address_snapshot AS addressSnapshot FROM after_sale a LEFT JOIN orders o ON o.id = a.order_id WHERE a.merchant_id = #{merchantId}
AND a.status = #{status}
AND ( o.order_no LIKE CONCAT('%', #{keyword}, '%') OR o.address_snapshot LIKE CONCAT('%', #{keyword}, '%') OR a.reason LIKE CONCAT('%', #{keyword}, '%') )
AND a.create_time >= #{startTime}
AND a.create_time <= #{endTime}
ORDER BY a.create_time DESC
